file.contenuto:
extends Sprite2D

var speed: float = 250.0


func _ready() -> void:
	modulate = Color.CYAN


func _process(delta: float) -> void:
	var direction: float = 0.0
	if Input.is_action_pressed("surface"):
		direction -= 1.0
	if Input.is_action_pressed("dive"):
		direction += 1.0

	position.y += direction * speed * delta
	position.y = clamp(position.y, 80.0, 560.0)
